import{_ as r,h as o,i as a,c as s,v as t,p as i,x as n,m,e as h,S as d}from"./chunks/framework.Dvtg8yj2.js";const S=JSON.parse('{"title":"Synthesizer","description":"","frontmatter":{"title":"Synthesizer","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthesizer.md","filePath":"llm/synthesizer.md","lastUpdated":1788454257000}'),p={name:"llm/synthesizer.md"};function f(_,e,R,E,c,k){const l=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="synthesizer" tabindex="-1">Synthesizer <a class="header-anchor" href="#synthesizer" aria-label="Permalink to &quot;Synthesizer&quot;">​</a></h1><div class="epigraph"><p>点积自注意力被当成 Transformer 不可缺少的内核，但随机对齐矩阵已经相当能打；合成权重不必来自查询与键的两两交互。</p><footer>—— Tay et al., Synthesizer: Rethinking Self-Attention for Transformer Models, ICML 2021</footer></div><p>缩放点积注意力把「谁该看谁」写成 \\(QK^\\top\\)，再 softmax 成行随机矩阵去乘值。Tay 等人 2021 年的问题更刺：这张对齐矩阵是否必须由 token–token 交互产生？他们用一组合成注意力（synthetic attention）替换点积，得到 Synthesizer：权重可以直接从单个 token 的表示投影出来，甚至可以是与输入无关的随机矩阵。实验上，简单的合成器在翻译、语言建模、GLUE/SuperGLUE 上与原 Transformer 接近；与点积拼在一起时往往更好；随机合成器相对动态卷积更快，困惑度也更低。本篇只写这篇论文的机制贡献，不把后续所有「去掉 \\(QK\\)」的工作算进 Synthesizer。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准自注意力的分数来自查询与键的相容性。这个设计有两层假设：第一，位置 \\(i\\) 对位置 \\(j\\) 的权重应当随当前内容改变；第二，改变的方式必须是一次双线性打分。第二层并不显然。若许多任务真正需要的只是「一种可学习的混合图案」，图案本身可以是全局的、与样本无关的，也可以只依赖单个位置的表示，而不依赖两两点积。</p><p>点积还有工程代价：\\(n\\times n\\) 的分数矩阵、额外的 \\(W_Q,W_K\\) 投影、以及随长度二次的显存。当时已经有固定稀疏图案、Linformer、动态卷积等替代。Synthesizer 要检验的不是「注意力能不能稀疏」，而是「对齐矩阵的信息来源」：拿掉 token–token 交互之后，Transformer 还剩多少能力。若随机矩阵已经够用，说明点积贡献被高估了；若从单 token 合成的权重也够用，说明内容寻址不必走 \\(q^\\top k\\)。<span class="marginnote">「随机也能工作」不是说注意力无用，而是说：在当时的模型宽度与任务上，可学习的混合图案本身就带很强的归纳偏置。点积是图案的一种生成器，不是唯一生成器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="dense-synthesizer-从单-token-合成一行权重" tabindex="-1">Dense Synthesizer：从单 token 合成一行权重 <a class="header-anchor" href="#dense-synthesizer-从单-token-合成一行权重" aria-label="Permalink to &quot;Dense Synthesizer：从单 token 合成一行权重&quot;">​</a></h3><p>对长度为 \\(\\ell\\)、宽度 \\(d\\) 的输入 \\(X\\)，Dense 变体不再计算 \\(QK^\\top\\)。每个位置 \\(i\\) 的表示 \\(X_i\\) 经过一个前馈 \\(F:\\mathbb{R}^d\\to\\mathbb{R}^\\ell\\)，直接产出对全部键位置的未归一化分数，再 softmax，去乘值投影 \\(G(X)\\)：</p> \\[Y=\\mathrm{softmax}\\bigl(F(X)\\bigr)\\,G(X). \\]<p>\\(F\\) 通常是两层：先压到较小的隐维，再扩到 \\(\\ell\\)。权重只依赖「我是谁」，不依赖「对方是谁」的键向量，因此没有 \\(Q\\)、\\(K\\) 投影。参数量大约是 \\(d\\times\\ell\\) 量级（加上值投影），相对点积省掉一对 \\(d\\times d\\) 矩阵，但多出与长度相关的投影，长序列会变沉。</p><h3 id="random-synthesizer-与输入无关的对齐" tabindex="-1">Random Synthesizer：与输入无关的对齐 <a class="header-anchor" href="#random-synthesizer-与输入无关的对齐" aria-label="Permalink to &quot;Random Synthesizer：与输入无关的对齐&quot;">​</a></h3><p>更极端的 Random 变体令 \\(R\\in\\mathbb{R}^{\\ell\\times\\ell}\\) 为随机初始化矩阵，可训练或冻结：</p> \\[Y=\\mathrm{softmax}(R)\\,G(X). \\]<p>每一头加 \\(\\ell^2\\) 个参数。对齐完全不看当前 token，只学一套任务级的全局混合。这是对固定注意力图案（如 Raganato 等人的固定模式）的直接推广：图案可以学习，但仍然与样本无关。作者原先预期它会崩，结果在多项任务上出乎意料地能打，成为论文最刺的经验结论之一。</p><h3 id="低秩分解与和点积的混合" tabindex="-1">低秩分解与和点积的混合 <a class="header-anchor" href="#低秩分解与和点积的混合" aria-label="Permalink to &quot;低秩分解与和点积的混合&quot;">​</a></h3><p>\\(\\ell\\) 一大，\\(d\\times\\ell\\) 或 \\(\\ell\\times\\ell\\) 都不可接受。Factorized Dense 把 \\(F(X_i)\\) 拆成两路较短的投影，再外积或逐元乘还原成长度为 \\(\\ell\\) 的分数，参数从 \\(O(\\ell)\\) 降到接近 \\(O(\\sqrt{\\ell})\\) 量级。Factorized Random 把 \\(R\\) 写成 \\(R_1 R_2^\\top\\)，其中 \\(R_1,R_2\\in\\mathbb{R}^{\\ell\\times k}\\)、\\(k\\ll\\ell\\)：</p> \\[Y=\\mathrm{softmax}(R_1 R_2^\\top)\\,G(X). \\]<p>混合 Synthesizer 再把合成分数与标准点积分数相加或拼接，让模型同时使用「内容寻址」和「合成图案」。论文报告：单独的合成器已有竞争力；与点积组合后稳定超过原 Transformer。相对 Linformer 一类只编码的低秩注意力，分解后的合成器在编码任务上也可以更好，说明低秩不必来自对 \\(K,V\\) 的随机投影，也可以来自对对齐矩阵本身的分解。<span class="marginnote">分解针对的是参数，不是把二次计算变成线性。未分解的 Random 在推理时仍要物化 \\(\\ell\\times\\ell\\) 的 softmax；分解后是低秩分数，乘 \\(V\\) 可以先乘小矩阵，这才有计算上的线性化空间。</span></p>',19)),(a(),i(d,null,{default:n(()=>[h(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%20X%22%5D%20--%3E%20D%5B%22Dense%3A%20%E5%8D%95%20token%20%E6%8A%95%E5%BD%B1%E6%88%90%E4%B8%80%E8%A1%8C%22%5D%0A%20%20X%20--%3E%20R%5B%22Random%3A%20%E5%85%A8%E5%B1%80%E7%9F%A9%E9%98%B5%20R%22%5D%0A%20%20X%20--%3E%20QK%5B%22%E5%8F%AF%E9%80%89%3A%20%E7%82%B9%E7%A7%AF%20QK%22%5D%0A%20%20D%20--%3E%20S%5B%22Softmax%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20R%20--%3E%20S%0A%20%20QK%20--%3E%20S%0A%20%20X%20--%3E%20G%5B%22%E5%80%BC%E6%8A%95%E5%BD%B1%20G(X)%22%5D%0A%20%20S%20--%3E%20Y%5B%22%E5%8A%A0%E6%9D%83%E8%BE%93%E5%87%BA%22%5D%0A%20%20G%20--%3E%20Y%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>点积注意力的梯度同时流过查询和键，迫使表示空间学会一种相容性度量。Dense Synthesizer 的梯度只流过「当前 token → 整行权重」的映射：它学的是位置相关的混合系数，更接近「每个位置一套动态卷积核」，而不是检索。Random 则连这层条件都去掉，梯度只更新全局 \\(R\\) 与值投影；网络把内容交互推到后面的前馈与残差里。</p><p>这解释了为何随机矩阵并不等于「没有注意力」。softmax\\((R)V\\) 仍是对值的凸组合，多层叠起来可以合成复杂的跨位置路由；缺的是随样本改变路由的能力。翻译和对齐敏感的任务更吃点积；分类、语言建模在当时规模下，一套好的全局图案已经能混到足够的上下文。把合成器与点积相加，等于给模型两条路由：一条内容寻址，一条任务先验。经验上后者不是噪声，而是正则。</p><p>长度外推是另一条裂缝。Dense 的 \\(F\\) 输出维绑死在训练长度 \\(\\ell\\) 上，换更长序列要改投影或插值；Random 的 \\(R\\) 同样是 \\(\\ell\\times\\ell\\) 的表。点积没有这张表，长度由 \\(QK^\\top\\) 的形状临时决定。合成注意力用参数换掉了内容交互，也把长度变成了架构常数。<span class="marginnote">不要把「不需要 \\(QK\\)」读成「注意力权重可以随便初始化」。Random 能工作，靠的是 softmax 之后仍是合法的行随机矩阵，以及足够深的残差把混合多次叠加。换成未归一化的 \\(R\\) 直接乘 \\(V\\)，尺度会漂。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Synthesizer 是 2021 年对「点积是否必要」的消融，不是今日长上下文的默认层。长序列上 Dense/Random 的参数随 \\(\\ell\\) 涨，分解缓解参数但不自动给出 Flash 级别的核。需要精确拷贝、指代消解、针测时，丢掉 \\(q^\\top k\\) 通常会伤检索；这时应保留点积或只在部分层替换。</p><p>与动态卷积相比，Random 更快是因为对齐可以预计算，卷积核随输入变则不能。这不意味着合成器在所有硬件上都更快：现代 FlashAttention 把点积的二次常数压得很低，短序列上再上一个未融合的 \\(\\ell\\times\\ell\\) softmax 没有优势。论文给出的 60% 加速、相对 3.5% 的困惑度改进，绑定在当时的动态卷积基线上，迁移时要重测。</p><p>因子化合成器可以当作廉价的位置先验，塞进混合架构：局部仍用窗口 softmax，全局用低秩 \\(R_1 R_2^\\top\\)。不要假设「随机注意力 = 无需训练」——可训练的 \\(R\\) 才是主结果；完全冻结的 Fixed Random 是更弱的对照，用来说明图案本身有用，不是推荐配方。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Synthesizer 用合成对齐矩阵替换 \\(QK^\\top\\)，检验 token–token 交互对 Transformer 是否必要。</li><li>Dense 从单 token 投影出一行权重；Random 用与输入无关的 \\(\\ell\\times\\ell\\) 矩阵；二者都可以低秩分解。</li><li>随机对齐在多项任务上出乎意料地有竞争力，说明点积不是性能的唯一来源。</li><li>与点积混合通常优于纯 Transformer；相对动态卷积，Random 更快且困惑度更低。</li><li>长度绑在参数表上，外推与超长序列不是主场。</li><li>精确检索仍更依赖内容寻址；合成器更适合当作可学习的混合先验。</li><li>出处：Tay et al., <em>Synthesizer: Rethinking Self-Attention for Transformer Models</em>, ICML 2021。</li></ul>',10))])}const y=r(p,[["render",f]]);export{S as __pageData,y as default};
